// === Tab: mySketch ===
const sketch = (p) => {
    const W = 1112;
    const H = 834;


    p.setup = () => {
        p.createCanvas(W, H);
    };

    function draw_leaf(r, angle) {
        let grad = p.drawingContext.createRadialGradient(0, 0, r/3, 0, 0, r*5);
        let red = p.random(200, 255);
        let g1 = p.random(100, 200);
        let g2 = p.random(0, g1);
        let co1 = p.color(red, g1, 0);
        let co2 = p.color(red, g2, 0);
        p.drawingContext.fillStyle = grad;

        grad.addColorStop(0,   co1.toString());
        grad.addColorStop(1.0, co2.toString());
        p.rotate(p.PI + angle);
        p.beginShape();
        let sc = p.random(1.5, 3);
        for(let a = 0; a < p.TWO_PI; a += p.TWO_PI/360){
            let r2 = r * 1.5 * (2.5 / sc)
                    * (sc + 0.9 * p.cos(8 * a))
                    * (1 + 0.1 * p.cos(24 * a))
                    * (0.9 + 0.1 * p.cos(200 * a)) * (1 + p.sin(a))
                    ;
            p.vertex(
                r2 * p.cos(a),
                r2 * p.sin(a)
            );
        }
        p.endShape(p.CLOSE);


        p.stroke(100, 0, 0);
        p.strokeWeight(1);
        for(let a = 0; a <= p.PI; a += p.TWO_PI/8){
            p.beginShape(p.LINES);
            let f = p.map(p.abs(a - p.PI/2), 0, p.PI/2, 7, 3);
            for(let i = 0; i < 20; ++i){
                p.vertex(r * f *(i/20) * p.cos(a) + r*p.random(0.05), r * f * (i/20) * p.sin(a) + r*p.random(0.05));
            }
            p.endShape();
        }

        p.noFill();
        p.stroke(red, g2, 0);
        p.strokeWeight(1);
        let dir = 0.1;
        if (p.random() < 0.5) {
            dir = -0.1;
        }
        let sr = r * p.random(0.7, 1.2);
        p.bezier(
            0, 0,
            sr * p.cos(p.PI * (1.5 + dir)), sr * p.sin(p.PI * (1.5 + dir)),
            sr * 3.5 * p.cos(p.PI * (1.5 + dir)), sr * 3.5 * p.sin(p.PI * (1.5 + dir)),
            sr*5 * p.cos(p.PI * 1.5), sr*5 * p.sin(p.PI * 1.5),
        );
        p.fill(red, g2, 0);
        p.rectMode(p.CENTER);
        p.rect(sr*5 * p.cos(p.PI * 1.5), sr*5 * p.sin(p.PI * 1.5), 4, 4);
    }

    p.draw = () => {
        p.background(30);

        p.noStroke();

        for(let i = 0; i < 70; ++i){
            let x = p.random(50, W-50);
            let y = p.random(50, H-50);
            let a = p.random(0, p.TWO_PI);
            p.push();
            p.translate(x, y);
            draw_leaf(8, a);
            p.pop();
        }

        p.noLoop();
    };

		p.mouseClicked = () => {
			  //p.save("img_.jpg");
			  p.save("img_" + p.month() + '-' + p.day() + '_' + p.hour() + '-' + p.minute() + '-' + p.second() + ".jpg");
				p.redraw();
		}
};


new p5(sketch);

